        b = set(map(tuple, blocked))
        n = len(blocked)
        limit = n * (n - 1) // 2

        def bfs(start, goal):
            seen = {tuple(start)}
            q = deque([tuple(start)])
            while q:
                x, y = q.popleft()
                if [x, y] == goal:
                    return True
                if len(seen) > limit:
                    return True
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < 10**6 and 0 <= ny < 10**6 and (nx, ny) not in b and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            return False

        return bfs(source, target) and bfs(target, source)

