class Solution {
public:
    bool isEscapePossible(vector<vector<int>>& blocked, vector<int>& source, vector<int>& target) {
        set<pair<long long,long long>> b;
        for (auto& c : blocked) b.insert({c[0], c[1]});
        long long n = blocked.size();
        long long limit = n * (n - 1) / 2;
        auto bfs = [&](vector<int>& s, vector<int>& g) {
            set<pair<long long,long long>> seen;
            queue<pair<long long,long long>> q;
            pair<long long,long long> st{s[0], s[1]};
            seen.insert(st); q.push(st);
            int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
            while (!q.empty()) {
                auto [x, y] = q.front(); q.pop();
                if (x == g[0] && y == g[1]) return true;
                if ((long long)seen.size() > limit) return true;
                for (auto& d : dirs) {
                    long long nx = x + d[0], ny = y + d[1];
                    if (nx < 0 || ny < 0 || nx >= 1000000 || ny >= 1000000) continue;
                    pair<long long,long long> p{nx, ny};
                    if (!b.count(p) && !seen.count(p)) { seen.insert(p); q.push(p); }
                }
            }
            return false;
        };
        return bfs(source, target) && bfs(target, source);
    }
};

