class Solution {
    public boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
        Set<Long> b = new HashSet<>();
        for (int[] c : blocked) b.add(enc(c[0], c[1]));
        long n = blocked.length;
        long limit = n * (n - 1) / 2;
        return bfs(source, target, b, limit) && bfs(target, source, b, limit);
    }

    private long enc(int x, int y) { return ((long) x << 20) | y; }

    private boolean bfs(int[] s, int[] g, Set<Long> b, long limit) {
        Set<Long> seen = new HashSet<>();
        Deque<long[]> q = new ArrayDeque<>();
        seen.add(enc(s[0], s[1]));
        q.add(new long[]{s[0], s[1]});
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!q.isEmpty()) {
            long[] cur = q.poll();
            int x = (int) cur[0], y = (int) cur[1];
            if (x == g[0] && y == g[1]) return true;
            if (seen.size() > limit) return true;
            for (int[] d : dirs) {
                int nx = x + d[0], ny = y + d[1];
                if (nx < 0 || ny < 0 || nx >= 1000000 || ny >= 1000000) continue;
                long p = enc(nx, ny);
                if (!b.contains(p) && !seen.contains(p)) { seen.add(p); q.add(new long[]{nx, ny}); }
            }
        }
        return false;
    }
}

