from collections import deque

class Solution:
    def isEscapePossible(self, blocked: List[List[int]], source: List[int], target: List[int]) -> bool:
        b = set(map(tuple, blocked))
        limit = len(blocked) * (len(blocked) - 1) // 2
        s0, t0 = tuple(source), tuple(target)
        vs, vt = {s0}, {t0}
        qs, qt = deque([s0]), deque([t0])
        dirs = ((1,0),(-1,0),(0,1),(0,-1))

        def expand(q, v, other):
            for _ in range(len(q)):
                x, y = q.popleft()
                for dx, dy in dirs:
                    p = (x + dx, y + dy)
                    if p in other:
                        return True
                    if 0 <= p[0] < 10**6 and 0 <= p[1] < 10**6 and p not in b and p not in v:
                        v.add(p)
                        q.append(p)
            return None

        while qs and qt:
            if len(qs) <= len(qt):
                r = expand(qs, vs, vt)
            else:
                r = expand(qt, vt, vs)
            if r is not None:
                return r
            if len(vs) > limit or len(vt) > limit:
                return True
        return False

