class Solution {
    public boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
        Set<Long> b = new HashSet<>();
        for (int[] c : blocked) b.add(((long) c[0] << 20) | c[1]);
        long n = blocked.length, limit = n * (n - 1) / 2;
        Set<Long> vs = new HashSet<>(Set.of(key(source))), vt = new HashSet<>(Set.of(key(target)));
        Deque<int[]> qs = new ArrayDeque<>(List.of(source)), qt = new ArrayDeque<>(List.of(target));
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!qs.isEmpty() && !qt.isEmpty()) {
            boolean met = qs.size() <= qt.size()
                ? step(qs, vs, vt, b, dirs) : step(qt, vt, vs, b, dirs);
            if (met) return true;
            if (vs.size() > limit || vt.size() > limit) return true;
        }
        return false;
    }

    private long key(int[] c) { return ((long) c[0] << 20) | c[1]; }

    private boolean step(Deque<int[]> q, Set<Long> v, Set<Long> o, Set<Long> b, int[][] dirs) {
        for (int sz = q.size(); sz > 0; sz--) {
            int[] cur = q.poll();
            for (int[] d : dirs) {
                int nx = cur[0] + d[0], ny = cur[1] + d[1];
                if (nx < 0 || ny < 0 || nx >= 1000000 || ny >= 1000000) continue;
                long p = ((long) nx << 20) | ny;
                if (o.contains(p)) return true;
                if (!b.contains(p) && !v.contains(p)) { v.add(p); q.add(new int[]{nx, ny}); }
            }
        }
        return false;
    }
}

